const resetComponentProjectWriteCapabilityStateForTest = () => { plans.clear(); activeImports.clear(); activeProcesses.clear(); operations.clear(); };
module.exports = { MAX_MUTATION_ITEMS, MAX_PROCESS_TIMES, PLAN_TTL_MS, registerComponentProjectWriteCapabilities, resetComponentProjectWriteCapabilityStateForTest };
